// Pseudo: precompute cost[p][i], then DP with backpointers
const n = s.length;
const INF = 1e9;
const cost = Array.from({ length: n }, () => Array(n).fill(0));
for (let p = 0; p < n; p++) {
  const seen = new Array(26).fill(false);
  let distinct = 0;
  for (let i = p; i < n; i++) {
    const idx = s.charCodeAt(i) - 97;
    if (!seen[idx]) { seen[idx] = true; distinct++; }
    cost[p][i] = distinct;
  }
}
const kCap = Math.min(k, n);
